<script>
document.addEventListener('DOMContentLoaded', function () {
    const input = document.getElementById('eduLessonMediaInput'); const preview = document.getElementById('eduLessonLocalPreview'); const type = document.getElementById('eduLessonContentType'); let objectUrl = null;
    input?.addEventListener('change', function () { preview.replaceChildren(); preview.hidden = true; if (objectUrl) URL.revokeObjectURL(objectUrl); const file = input.files?.[0]; if (!file) return; objectUrl = URL.createObjectURL(file); let player; if (file.type.startsWith('video/')) { player = document.createElement('video'); player.controls = true; player.playsInline = true; } else if (file.type.startsWith('audio/')) { player = document.createElement('audio'); player.controls = true; } else return; player.src = objectUrl; preview.appendChild(player); preview.hidden = false; if (type && file.type.startsWith('audio/')) type.value = 'audio'; else if (type && file.type.startsWith('video/')) type.value = 'video'; });
});
</script>
@endpush
